function stripQuoted(text) {
  const lines = String(text || '').split(/\r?\n/);
  const out = [];
  for (const line of lines) {
    if (/^\s*(Em .+escreveu:|On .+wrote:|-----\s*Original Message|De:\s.+|From:\s.+)$/i.test(line) && out.length > 0) break;
